typedef unsigned int u_int;
typedef unsigned long u_long;
typedef unsigned int u_long128 __attribute__((mode(TI)));

struct sceGifTag {
  u_long NLOOP : 15;
  u_long EOP : 1;
  u_long pad16 : 30;
  u_long PRE : 1;
  u_long PRIM : 11;
  u_long FLG : 2;
  u_long NREG : 4;
  u_long REGS0 : 4;
  u_long regs_rest : 60;
};
struct sceGsDrawEnv { char pad[128]; u_long xyoffset1; };
struct sceGsDBuff { sceGifTag giftag0; sceGsDrawEnv draw0; };
struct sceGifPacket { u_long128* pBase; u_long128* pCurrent; };
struct sceDmaChan;
class movieplayer {
public:
  char hiRes;
  sceGsDBuff db;
  void clearGsMem(int r, int g, int b, int disp_width, int disp_height);
};

sceDmaChan* sceDmaGetChan(int);
void sceGsSetDefDrawEnv(sceGsDrawEnv*, int, int, int, int, int);
void FlushCache(int);
void sceGsSyncPath(int, int);
void sceGsPutDrawEnv(sceGifTag*);
void sceGifPkInit(sceGifPacket*, u_long128*);
void sceGifPkReset(sceGifPacket*);
void sceGifPkEnd(sceGifPacket*, int, int, int);
void sceGifPkOpenGifTag(sceGifPacket*, u_long128);
void sceGifPkAddGsAD(sceGifPacket*, int, u_long);
void sceGifPkCloseGifTag(sceGifPacket*);
void sceGifPkTerminate(sceGifPacket*);
void sceDmaSend(sceDmaChan*, u_long128*);

#define SCE_DMA_GIF 2
#define SCE_GS_PSMCT32 0
#define SCE_GS_PRIM 0
#define SCE_GS_RGBAQ 1
#define SCE_GS_XYZ2 5
#define MAX_WIDTH 640
#define MAX_HEIGHT 448
#define SCE_GIF_SET_TAG(nloop,eop,pre,prim,flg,nreg) ((u_long)(nloop) | ((u_long)(eop)<<15) | ((u_long)(pre)<<46) | ((u_long)(prim)<<47) | ((u_long)(flg)<<58) | ((u_long)(nreg)<<60))
#define SCE_GIF_CLEAR_TAG(tag) (*(u_long128*)(tag)=0)
#define SCE_GS_SET_XYOFFSET_1(x,y) ((u_long)(x) | ((u_long)(y)<<32))
#define SCE_GS_SET_PRIM(prim,iip,tme,fge,abe,aa1,fst,ctxt,fix) ((u_long)(prim) | ((u_long)(iip)<<3) | ((u_long)(tme)<<4) | ((u_long)(fge)<<5) | ((u_long)(abe)<<6) | ((u_long)(aa1)<<7) | ((u_long)(fst)<<8) | ((u_long)(ctxt)<<9) | ((u_long)(fix)<<10))
#define SCE_GS_SET_RGBAQ(r,g,b,a,q) ((u_long)(r) | ((u_long)(g)<<8) | ((u_long)(b)<<16) | ((u_long)(a)<<24) | ((u_long)(q)<<32))
#define SCE_GS_SET_XYZ2(x,y,z) ((u_long)(x) | ((u_long)(y)<<16) | ((u_long)(z)<<32))
#define bound(x,b) (((x)+(b)-1)&~((b)-1))

void movieplayer::clearGsMem( int r, int g, int b, int disp_width, int disp_height )
{
  const u_long    giftag_clear[2] = { SCE_GIF_SET_TAG(0, 1, 0, 0, 0, 1), 0x000000000000000eL };
  sceGifPacket    packet;
  u_long128       packetBase[6] __attribute__ ((aligned(16)));

  sceDmaChan* dmaGif = sceDmaGetChan(SCE_DMA_GIF);
  SCE_GIF_CLEAR_TAG( &db.giftag0 );
  db.giftag0.NLOOP = 8;
  db.giftag0.EOP = 1;
  db.giftag0.NREG = 1;
  db.giftag0.REGS0 = 0xe;

  sceGsSetDefDrawEnv( &db.draw0, SCE_GS_PSMCT32, disp_width, bound(disp_height/2, 32)*2 + bound(disp_height, 32)*2, 0, 0 );
  *(u_long *)&db.draw0.xyoffset1 = SCE_GS_SET_XYOFFSET_1( 0, 0 );
  FlushCache( 0 );
  sceGsSyncPath( 0, 0 );
  sceGsPutDrawEnv( &db.giftag0 );
  sceGifPkInit( &packet, packetBase );
  sceGifPkReset( &packet );
  sceGifPkEnd(&packet, 0, 0, 0);
  sceGifPkOpenGifTag( &packet, *(u_long128*)&giftag_clear );
  sceGifPkAddGsAD( &packet, SCE_GS_PRIM, SCE_GS_SET_PRIM(6, 0, 0, 0, 0, 0, 0, 0, 0) );
  sceGifPkAddGsAD( &packet, SCE_GS_RGBAQ, SCE_GS_SET_RGBAQ(r, g, b, 0, 0) );
  sceGifPkAddGsAD( &packet, SCE_GS_XYZ2, SCE_GS_SET_XYZ2(0 << 4,0 << 4, 0) );
  sceGifPkAddGsAD( &packet, SCE_GS_XYZ2, SCE_GS_SET_XYZ2( MAX_WIDTH << 4, MAX_HEIGHT*5 << 4, 0) );
  sceGifPkCloseGifTag( &packet );
  sceGifPkTerminate( &packet );
  FlushCache( 0 );
  sceGsSyncPath( 0, 0 );
  sceDmaSend( dmaGif, (u_long128*)(u_int)packet.pBase );
  sceGsSyncPath( 0, 0 );
}
